 * Compute the longest common subsequence of `side` against `base`
 * (arrays of strings, compared for exact equality), and return the list
 * of changes needed to turn `base` into `side`.
 *
 * Each change is `{ baseStart, baseEnd, sideStart, sideEnd }`: the base
 * lines `base[baseStart:baseEnd]` are replaced by `side[sideStart:sideEnd]`.
 *
 * Among LCSs of equal length, the one whose matches come earliest is
 * chosen: walking both documents from the start, a match is taken
 * whenever the two current lines are equal, and otherwise the side whose
 * remaining subsequence is at least as long as the other's is advanced,
 * preferring to advance the base when they tie.
 */
export function diffAgainstBase(side, base) {
  const n = side.length
  const m = base.length

  // L[i * (m + 1) + j] = LCS length of side[i:] and base[j:]
  const width = m + 1
  const L = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    const rowCur = i * width
    const rowNext = (i + 1) * width
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        L[rowCur + j] = L[rowNext + j + 1] + 1
      } else {
        const skipSide = L[rowNext + j]
        const skipBase = L[rowCur + j + 1]
        L[rowCur + j] = skipSide > skipBase ? skipSide : skipBase
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advSide = L[(i + 1) * width + j]
      const advBase = L[i * width + (j + 1)]
      if (advSide > advBase) {
        i++
      } else {
        j++
      }
    }
  }

  const changes = []
  let li = 0
  let lj = 0
  for (const [mi, mj] of matches) {
    if (mi > li || mj > lj) {
      changes.push({ baseStart: lj, baseEnd: mj, sideStart: li, sideEnd: mi })
    }
    li = mi + 1
    lj = mj + 1
  }
  if (li < n || lj < m) {
    changes.push({ baseStart: lj, baseEnd: m, sideStart: li, sideEnd: n })
  }

  return changes
}
"}

