  if (changes.length === 0) return base.slice(start, end)
  const result = []
  let pos = start
  for (const c of changes) {
    for (let k = pos; k < c.baseStart; k++) result.push(base[k])
    for (let k = c.sideStart; k < c.sideEnd; k++) result.push(c.sideLines[k - c.sideStart])
    pos = c.baseEnd
