{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { mergeDocuments } from './merge.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function parseInput(raw) {
  let lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }

  if (docs.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }

  return docs
}

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

